        /// The colour a state's dot and its glow are filled with; anything unknown is idle grey.
        internal static Color StatusFill(string state)
        {
            if (state == "monitoring" || state == "waiting" || state == "checking" || state == "recovering") return Active;
            if (state == "attention") return Attention;
            if (state == "failed") return Danger;
            if (state == "paused") return Paused;
            return Idle;
        }

        /// The same dot in High Contrast: a system colour, and never a glow.
        internal static Color StatusSystem(string state)
        {
            if (state == "monitoring" || state == "waiting" || state == "checking" || state == "recovering") return SystemColors.Highlight;
            if (state == "attention" || state == "failed") return SystemColors.WindowText;
            return SystemColors.GrayText;
        }

        /// The status light for one frame, or false when the light is off: brand.glow() in C#. `dim` is
        /// how far the dot is drawn from its colour toward the ground under it, `opacity` multiplies the
        /// glow's falloff, `spread` is how far out the glow is - 0 none, 1 GlowReach past the dot's edge -
        /// and `arc` is the checking arc's start angle in degrees, or -1. Every light that moves loops on
        /// elapsedMs; sinceEnteredMs is what a problem's one pulse ran on until v0.6.8 and is read by
        /// nothing now. The caller neither dims the dot nor draws a glow in High Contrast.
        internal static bool Glow(string state, double elapsedMs, double sinceEnteredMs, bool reduced,
                                  out double dim, out double opacity, out double spread, out double arc)
        {
            dim = 0;
            opacity = 0;
            spread = 0;
            arc = -1;
            if (state == "monitoring")
                return reduced || Light(elapsedMs % GlowMonitoringMs / GlowMonitoringMs, out dim, out opacity, out spread);
            if (state == "waiting")
                return reduced || Light(elapsedMs % GlowWaitingMs / GlowWaitingMs, out dim, out opacity, out spread);
            if (state == "recovering")
                return reduced || Light(elapsedMs % GlowRecoveringMs / GlowRecoveringMs, out dim, out opacity, out spread);
            if (state == "attention")
                return reduced || Light(elapsedMs % GlowAttentionMs / GlowAttentionMs, out dim, out opacity, out spread);
            if (state == "failed")
                return reduced || Light(elapsedMs % GlowFailedMs / GlowFailedMs, out dim, out opacity, out spread);
            if (state == "checking")
            {
                arc = reduced ? GlowArcStillAt : elapsedMs % GlowArcMs / GlowArcMs * 360.0;
                return true;
            }
            return false;
        }

        /// Whether a frame timer has anything to draw for this state: every breathing state and checking's
        /// arc, for as long as the state lasts.
        internal static bool GlowMoves(string state, double sinceEnteredMs, bool reduced)
        {
            return !reduced && (state == "monitoring" || state == "waiting" || state == "recovering" || state == "attention" || state == "failed" || state == "checking");
        }

        /// The light at `fraction` of one breath (brand.glow_phase): a cosine in light, raised to
        /// 1/gamma to be drawn, with the glow riding the brightness rather than taking a turn of its own.
        private static bool Light(double fraction, out double dim, out double opacity, out double spread)
        {
            double breath = 0.5 + 0.5 * Math.Cos(2.0 * Math.PI * (fraction - Math.Floor(fraction)));
            double lit = Math.Pow(GlowLow + (1.0 - GlowLow) * breath, 1.0 / GlowGamma);
            double floor = Math.Pow(GlowLow, 1.0 / GlowGamma);
            double risen = (lit - floor) / (1.0 - floor);
            dim = 1.0 - lit;
            spread = risen * risen;
            opacity = GlowPeak * spread;
            return true;
        }

        /// 0 at the start of a cycle, 1 halfway, 0 again: a raised cosine.
        private static double Breath(double elapsedMs, double cycleMs)
        {
            return 0.5 - 0.5 * Math.Cos(2 * Math.PI * (elapsedMs % cycleMs) / cycleMs);
        }

        /// How far a transition has come, 0 to 1, after `progress` of TransitionMs: brand.ease(), the
        /// CSS cubic-bezier TransitionEaseX1, Y1, X2, Y2. Held at 0 before the start and 1 after the end.
        internal static double Ease(double progress)
        {
            if (!(progress > 0)) return 0;
            if (progress >= 1) return 1;
            double t = progress;
            for (int i = 0; i < 8; i++)
            {
                double error = Bezier(TransitionEaseX1, TransitionEaseX2, t) - progress;
                if (Math.Abs(error) < 1e-7) return Bezier(TransitionEaseY1, TransitionEaseY2, t);
                double slope = BezierSlope(TransitionEaseX1, TransitionEaseX2, t);
                if (Math.Abs(slope) < 1e-6) break;
                t = Math.Min(1.0, Math.Max(0.0, t - error / slope));
            }
            double low = 0, high = 1;
            t = progress;
            for (int i = 0; i < 40; i++)
            {
                double value = Bezier(TransitionEaseX1, TransitionEaseX2, t);
                if (Math.Abs(value - progress) < 1e-7) break;
                if (value < progress) low = t; else high = t;
                t = (low + high) / 2.0;
            }
            return Bezier(TransitionEaseY1, TransitionEaseY2, t);
        }

        private static double Bezier(double a, double b, double t)
        {
            return ((1.0 - 3.0 * b + 3.0 * a) * t + (3.0 * b - 6.0 * a)) * t * t + 3.0 * a * t;
        }

        private static double BezierSlope(double a, double b, double t)
        {
            return 3.0 * (1.0 - 3.0 * b + 3.0 * a) * t * t + 2.0 * (3.0 * b - 6.0 * a) * t + 3.0 * a;
        }

