            internal static readonly Color Raised        = Color.FromArgb(0x21, 0x28, 0x35);  // #212835, a control resting on a card
            internal static readonly Color Inset         = Color.FromArgb(0x12, 0x18, 0x20);  // #121820, pressed, selected, a well
            internal static readonly Color ShadowDark    = Color.FromArgb(0x05, 0x08, 0x0C);  // #05080C, shadow below and right of a raised surface
            internal static readonly Color ShadowLight   = Color.FromArgb(0x27, 0x30, 0x3D);  // #27303D, highlight above and left of it
            internal static readonly Color AccentSoft    = Color.FromArgb(0x1B, 0x2D, 0x45);  // #1B2D45, a quiet accent ground
            internal static readonly Color Focus         = Color.FromArgb(0x7D, 0xB6, 0xF5);  // #7DB6F5, keyboard focus ring
            internal static readonly Color Attention     = Color.FromArgb(0xE0, 0x9B, 0x57);  // #E09B57, fill only: needs a person
            internal static readonly Color Success       = Color.FromArgb(0x5C, 0xC9, 0x8E);  // #5CC98E, recovered
            internal static readonly Color Waiting       = Color.FromArgb(0x7D, 0xB6, 0xF5);  // #7DB6F5, waiting for a reset or retry
            internal static readonly Color Warning       = Color.FromArgb(0xE8, 0xA7, 0x65);  // #E8A765, needs a decision soon
            internal static readonly Color Danger        = Color.FromArgb(0xF2, 0x87, 0x7C);  // #F2877C, stopped or failed
            internal static readonly Color Paused        = Color.FromArgb(0x9A, 0xAC, 0xBF);  // #9AACBF, deliberately quiet
            internal static readonly Color AccentHover   = Color.FromArgb(0x62, 0xAD, 0xFF);  // #62ADFF, the primary button under the pointer
            internal static readonly Color AccentPressed = Color.FromArgb(0x52, 0x90, 0xD3);  // #5290D3, the primary button pressed
            internal static readonly Color CardGround    = Color.FromArgb(0x1B, 0x21, 0x2C);  // #1B212C, a card's own ground: surface lifted toward raised

            // How far each dark elevation recipe reaches past its box, in CSS px (brand.reach).
            internal const int ElevCardReachLeft = 27;
            internal const int ElevCardReachTop = 21;
            internal const int ElevCardReachRight = 27;
            internal const int ElevCardReachBottom = 33;
            internal const int ElevControlReachLeft = 3;
            internal const int ElevControlReachTop = 2;
            internal const int ElevControlReachRight = 3;
            internal const int ElevControlReachBottom = 4;
            internal const int ElevInsetReachLeft = 0;
            internal const int ElevInsetReachTop = 0;
            internal const int ElevInsetReachRight = 0;
            internal const int ElevInsetReachBottom = 0;

            /// The colour a state's dot and its glow are filled with; anything unknown is idle grey.
            internal static Color StatusFill(string state)
            {
                if (state == "monitoring" || state == "waiting" || state == "checking" || state == "recovering") return Active;
                if (state == "attention") return Attention;
                if (state == "failed") return Danger;
                if (state == "paused") return Paused;
                return Idle;
            }

            /// The check box's fill (brand.CHECKBOX): the well unchecked, the accent checked, the surface
            /// when disabled. `on` is checked; draw the inset elevation inside the border when CheckWell.
            internal static Color CheckFill(bool on, bool enabled)
            {
                if (!on && enabled) return Inset;
                if (on && enabled) return Accent;
                return Surface;
            }

            /// The check box's hairline edge: muted unchecked, where nothing inside says it is a box.
            internal static Color CheckEdge(bool on, bool enabled)
            {
                if (!on && enabled) return Muted;
                if (on && enabled) return Accent;
                return Line;
            }

            /// The check mark's colour, or false when the box has no mark.
            internal static bool CheckMark(bool on, bool enabled, out Color mark)
            {
                mark = Color.Empty;
                if (on && enabled) { mark = OnAccent; return true; }
                if (on && !enabled) { mark = Muted; return true; }
                return false;
            }

            /// How many shadows an elevation recipe ("card", "control" or "inset") has; 0 for any other.
            internal static int ElevationCount(string recipe)
            {
                if (recipe == "card") return 3;
                if (recipe == "control") return 1;
                if (recipe == "inset") return 1;
                return 0;
            }

            /// Shadow `index` of an elevation recipe (brand.SHADOWS), front to back as the panel's
            /// stylesheet lists them, so paint from the last to the first. In CSS px: the offset, the
            /// blur (a Gaussian with sigma blur / 2), the alpha, whether it falls inside the box rather
            /// than around it, and its colour. False past the last shadow.
            internal static bool ElevationShadow(string recipe, int index, out double dx, out double dy,
                                                 out double blur, out double alpha, out bool inset, out Color tone)
            {
                dx = 0;
                dy = 0;
                blur = 0;
                alpha = 0;
                inset = false;
                tone = Color.Empty;
                if (recipe == "card")
                {
                    if (index == 0) { dx = 0; dy = 1; blur = 2; alpha = 0.7; tone = ShadowDark; return true; }
                    if (index == 1) { dx = 0; dy = 6; blur = 18; alpha = 0.35; tone = ShadowDark; return true; }
                    if (index == 2) { dx = 0; dy = 1; blur = 0; alpha = 0.45; inset = true; tone = ShadowLight; return true; }
                    return false;
                }
                if (recipe == "control")
                {
                    if (index == 0) { dx = 0; dy = 1; blur = 2; alpha = 0.6; tone = ShadowDark; return true; }
                    return false;
                }
                if (recipe == "inset")
                {
                    if (index == 0) { dx = 0; dy = 1; blur = 2; alpha = 0.55; inset = true; tone = ShadowDark; return true; }
                    return false;
                }
                return false;
            }
        }

